import {SCHEMA,MAX_BYTES,exportCorrection,importCorrection} from './correction-sidecar.js';
const $=id=>document.getElementById(id),form=$('correction-form');let prepared=null,epoch=0;
const tell=text=>{$('correction-status').textContent=text;};
function invalidate(){epoch++;prepared=null;$('inspection').hidden=true;$('preview').textContent='';}
// Input fires for text and native selects. A later blur/change must not erase a freshly reopened inspection.
form.addEventListener('input',invalidate);
function proposal(){return {schema:SCHEMA,source:{url:$('source-url').value,archiveItem:$('archive-item').value,filename:$('filename').value,version:$('version').value,sha256:$('source-hash').value||null,locator:$('locator').value},original:$('original').value,proposed:$('proposed').value,reason:$('reason').value,uncertainty:$('uncertainty').value,attribution:{contributor:$('contributor').value,assistance:$('assistance').value},createdAt:new Date().toISOString(),previousDigest:$('previous').value||null};}
function inspect(raw){prepared=raw;$('preview').textContent=raw;$('inspection').hidden=false;$('preview').focus();}
form.onsubmit=async event=>{event.preventDefault();const ticket=++epoch;prepared=null;$('inspection').hidden=true;try{const raw=await exportCorrection(proposal());if(ticket!==epoch)throw Error('The form changed while preparing. Inspect a fresh export.');inspect(raw);tell('Prepared locally. Inspect the exact fields below before downloading. Digest is not a signature or approval.');}catch(e){tell(e.message);}};
$('download').onclick=()=>{if(!prepared)return;const url=URL.createObjectURL(new Blob([prepared],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='correction-sidecar.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);tell('Correction downloaded. No submission or source-file upload occurred.');};
$('reopen').onchange=async event=>{const file=event.target.files[0];if(!file)return;const ticket=++epoch;prepared=null;$('inspection').hidden=true;$('preview').textContent='';try{if(file.size>MAX_BYTES)throw Error('Choose a correction under 64 KiB, never a source document');const raw=await file.text(),packet=await importCorrection(raw);if(ticket!==epoch)throw Error('The form changed while checking. Reopen the file again.');inspect(raw);tell('Digest checked. Displayed file is an inspection copy; the form above is unchanged. Attribution and correctness remain unverified. '+packet.proposal.attribution.assistance);}catch(e){tell(e.message);}finally{event.target.value='';}};
